import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const DAY_MS = 24 * 60 * 60 * 1000;

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => startOfDay(new Date(Date.now() - days * DAY_MS));

const presets = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week-ago', label: 'Неделя назад', days: 7 },
];

const isSameDay = (a: Date | null, b: Date | null) =>
  a != null && b != null && startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [innerValue, setInnerValue] = useState<Date | null>(defaultValue);
  const selected = value !== undefined ? value : innerValue;

  const commit = (next: Date | null) => {
    if (value === undefined) setInnerValue(next);
    onChange?.(next);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 12,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}
      >
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.days);
          const active = isSameDay(selected, presetDate);
          return (
            <JxChip
              key={preset.id}
              active={active}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => commit(presetDate)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  commit(presetDate);
                }
              }}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>

      <JxCalendar locale="ru-RU" value={selected} onValueChange={commit} />

      <p
        aria-live="polite"
        style={{ margin: 0, fontSize: 14, color: selected ? 'var(--jx-text-2)' : 'var(--jx-text-3)' }}
      >
        {selected
          ? `Дата отчёта: ${selected.toLocaleDateString('ru-RU', {
              day: 'numeric',
              month: 'long',
              year: 'numeric',
            })}`
          : 'Дата не выбрана — выберите день в календаре или нажмите быстрый вариант.'}
      </p>
    </div>
  );
}

